    private static byte[] LoadImage()
    {
        ReadOnlySpan<byte> encoded = ImageBase64;
        byte[] buffer = new byte[Base64.GetMaxDecodedFromUtf8Length(encoded.Length)];
        Base64.DecodeFromUtf8(encoded, buffer, out _, out int written);
        return written == buffer.Length ? buffer : buffer.AsSpan(0, written).ToArray();
    }

    private static Regex? GetRegex(int index, string pattern)
    {
#if NET8_0_OR_GREATER && !DYNAMIC_BUILD
        switch (index)
        {
            case 0:
                return Regex0();
            case 1:
                return Regex1();
            case 2:
                return Regex2();
            default:
                return null;
        }
#else
        return null;
#endif
